mapper.insert:
INSERT INTO CHAT_ROOM (
    SENDER_EMAIL
    , RECEIVER_EMAIL
) VALUES (
    #{senderEmail}
    , #{receiverEmail}
)

mapper.select:
SELECT
    ID AS id
    , SENDER_EMAIL AS senderEmail
    , RECEIVER_EMAIL AS receiverEmail
FROM
    CHAT_ROOM
WHERE
    (
        SENDER_EMAIL = #{senderEmail}
        AND
        RECEIVER_EMAIL = #{receiverEmail}
    )
    OR
    (
        SENDER_EMAIL = #{receiverEmail}
        AND
        RECEIVER_EMAIL = #{senderEmail}
    )

mapper.insert:
INSERT INTO CHAT_MESSAGE (
    ROOM_ID
    , SENDER_EMAIL
    , CONTENT
) VALUES (
    #{roomId}
    , #{senderEmail}
    , #{content}
)
